INSERT INTO appointments (hospital_id,doctor_id,patient_id,scheduled_at,status,diagnosis_text,diagnosis_code)
    SELECT h.id, (SELECT d.id FROM doctors d WHERE d.hospital_id = h.id ORDER BY d.full_name LIMIT 1),
           COALESCE(p.merged_into, p.id), '2026-07-24T11:15:00.000Z', 'scheduled', 'HT', 'I10'
    FROM hospitals h, patients p WHERE h.code='JPR-FORT' AND p.mrn='PT-100710';
